import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Ética e Limites do Cultivo","description":"","frontmatter":{},"headers":[],"relativePath":"pt/19-修炼伦理与边界.md","filePath":"pt/19-修炼伦理与边界.md","lastUpdated":null}'),s={name:"pt/19-修炼伦理与边界.md"};function r(d,o,n,c,u,l){return e(),i("div",null,[...o[0]||(o[0]=[t('<h1 id="etica-e-limites-do-cultivo" tabindex="-1">Ética e Limites do Cultivo <a class="header-anchor" href="#etica-e-limites-do-cultivo" aria-label="Permalink to &quot;Ética e Limites do Cultivo&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>19</td></tr><tr><td>Módulo</td><td>Leis Cósmicas e Sistemas de Cultivo</td></tr><tr><td>Palavras-chave</td><td>Ética do Cultivo, Limites, Tabus, Linha de Base Ética, Exame Ético</td></tr></tbody></table><h2 id="i-definicao-e-posicao-da-etica-do-cultivo" tabindex="-1">I. Definição e Posição da Ética do Cultivo <a class="header-anchor" href="#i-definicao-e-posicao-da-etica-do-cultivo" aria-label="Permalink to &quot;I. Definição e Posição da Ética do Cultivo&quot;">​</a></h2><p>A ética do cultivo é a soma dos princípios morais e normas jurídicas na Civilização Simbiótica de Âncora que regulamentam o comportamento dos cultivadores, delimitam os limites do cultivo e mantêm a ordem do cultivo. Na era do saque, o cultivo era visto como um &quot;privilégio dos poderosos&quot;, e os cultivadores podiam usar qualquer meio para aumentar seu poder — devorar a origem de outros, escravizar a alma de outros, saquear os recursos de outros, realizar experimentos de cultivo desumanos, etc., eram comportamentos comuns. Essa cultura de cultivo de &quot;poder acima de tudo, ética nula&quot; é a base espiritual mais profunda do sistema de saque.</p><p>Após o estabelecimento da Civilização Simbiótica de Âncora, a construção da ética do cultivo foi adotada como uma das construções espirituais mais centrais. A proposição central da ética do cultivo é: &quot;A obtenção e o uso do poder devem estar sujeitos a restrições éticas&quot;. A civilização simbiótica acredita que o cultivo não é um assunto puramente pessoal, mas um assunto público que envolve outros, a civilização e o universo como um todo. Ao buscar o aumento de seu próprio poder, o cultivador deve respeitar os direitos dos outros, manter a ordem da civilização e proteger a ecologia do universo. A ética do cultivo não é uma restrição ao cultivo, mas uma proteção ao cultivo — ela garante que o cultivo sempre permaneça no caminho correto da &quot;evolução simbiótica&quot;, em vez de deslizar para o abismo da &quot;destruição por saque&quot;.</p><p>A ética do cultivo ocupa uma posição elevada no sistema jurídico da civilização simbiótica. A Constituição Simbiótica estabelece claramente os princípios básicos da ética do cultivo, o Tribunal de Âncora tem um &quot;Tribunal Ético&quot; especial para julgar casos de ética do cultivo, e a certificação de reino de todos os cultivadores avançados deve passar por exame ético. A ética do cultivo não é uma &quot;restrição suave&quot; opcional, mas uma &quot;norma rígida&quot; com força coercitiva.</p><h2 id="ii-principios-basicos-da-etica-do-cultivo" tabindex="-1">II. Princípios Básicos da Ética do Cultivo <a class="header-anchor" href="#ii-principios-basicos-da-etica-do-cultivo" aria-label="Permalink to &quot;II. Princípios Básicos da Ética do Cultivo&quot;">​</a></h2><h3 id="_2-1-principio-da-dignidade-da-vida" tabindex="-1">2.1 Princípio da Dignidade da Vida <a class="header-anchor" href="#_2-1-principio-da-dignidade-da-vida" aria-label="Permalink to &quot;2.1 Princípio da Dignidade da Vida&quot;">​</a></h3><p>Cada vida tem dignidade e valor invioláveis, e nenhum comportamento de cultivo pode ocorrer às custas da dignidade da vida. Especificamente inclui:</p><ul><li>É proibido usar outras vidas como &quot;materiais&quot; ou &quot;ferramentas&quot; de cultivo</li><li>É proibido realizar experimentos de cultivo desumanos (como dissecção viva, tortura de alma, etc.)</li><li>É proibido escravizar ou controlar a vontade livre de outras vidas</li><li>Respeitar o direito de cada vida de escolher seu próprio caminho evolutivo, não forçar outros a cultivar de acordo com seu próprio modo</li></ul><h3 id="_2-2-principio-antissaque" tabindex="-1">2.2 Princípio Antissaque <a class="header-anchor" href="#_2-2-principio-antissaque" aria-label="Permalink to &quot;2.2 Princípio Antissaque&quot;">​</a></h3><p>O cultivo deve ser baseado no ciclo simbiótico e não pode usar o saque de outros como meio. Especificamente inclui:</p><ul><li>É proibido devorar ou saquear a origem, energia e sorte de outras vidas</li><li>É proibido aumentar a própria velocidade de cultivo ou reino prejudicando outros</li><li>É proibido monopolizar recursos de cultivo para obter lucros indevidos</li><li>É proibido usar &quot;a lei do mais forte&quot; como desculpa para justificar comportamentos de saque</li></ul><h3 id="_2-3-principio-do-consentimento-informado" tabindex="-1">2.3 Princípio do Consentimento Informado <a class="header-anchor" href="#_2-3-principio-do-consentimento-informado" aria-label="Permalink to &quot;2.3 Princípio do Consentimento Informado&quot;">​</a></h3><p>Comportamentos de cultivo que envolvem outros (como herança mestre-discípulo, cultivo duplo de parceiros, compartilhamento de energia, experimentos de cultivo, etc.) devem ser realizados sob a premissa de que a outra parte está totalmente informada e concorda voluntariamente. Especificamente inclui:</p><ul><li>Explicar plenamente à outra parte o conteúdo, riscos e benefícios do comportamento de cultivo</li><li>Garantir que a outra parte tenha capacidade total de julgamento autônomo, não esteja sob coação ou suborno</li><li>A outra parte tem o direito de desistir a qualquer momento, não pode ser forçada a continuar</li><li>Para indivíduos menores ou mentalmente incapazes, seus guardiões exercem o direito de consentimento com base em avaliação profissional</li></ul><h3 id="_2-4-principio-do-dano-minimo" tabindex="-1">2.4 Princípio do Dano Mínimo <a class="header-anchor" href="#_2-4-principio-do-dano-minimo" aria-label="Permalink to &quot;2.4 Princípio do Dano Mínimo&quot;">​</a></h3><p>O comportamento de cultivo deve evitar, tanto quanto possível, causar danos a outros e ao meio ambiente. Em situações em que algum impacto é inevitável, deve-se escolher o método com menor dano e fornecer compensação razoável pelos danos causados. Especificamente inclui:</p><ul><li>Experimentos de cultivo são realizados preferencialmente em espaços isolados para evitar a disseminação de riscos</li><li>Cultivos do tipo batalha são realizados tanto quanto possível em campos de cultivo especiais para evitar danos ao ambiente público</li><li>Limpar e reparar prontamente a poluição de energia, danos espaciais, etc., gerados durante o processo de cultivo</li><li>É proibido realizar atividades de cultivo de alto risco em áreas densamente povoadas</li></ul><h3 id="_2-5-principio-da-honestidade" tabindex="-1">2.5 Princípio da Honestidade <a class="header-anchor" href="#_2-5-principio-da-honestidade" aria-label="Permalink to &quot;2.5 Princípio da Honestidade&quot;">​</a></h3><p>O cultivador deve manter a honestidade em assuntos relacionados ao cultivo e não deve fraudar. Especificamente inclui:</p><ul><li>É proibido forjar reino de cultivo, valor de contribuição, resultados de exame, etc.</li><li>É proibido fraudar ou plagiar em experiências de cultivo e resultados de pesquisa</li><li>É proibido fornecer informações falsas em solicitações de recursos e propostas de projetos</li><li>É proibido enganar os recursos de cultivo ou a confiança de outros com promessas falsas</li></ul><h3 id="_2-6-principio-da-responsabilidade" tabindex="-1">2.6 Princípio da Responsabilidade <a class="header-anchor" href="#_2-6-principio-da-responsabilidade" aria-label="Permalink to &quot;2.6 Princípio da Responsabilidade&quot;">​</a></h3><p>Quanto maior o poder, maior a responsabilidade. Os cultivadores avançados devem assumir responsabilidades públicas compatíveis com seu poder. Especificamente inclui:</p><ul><li>Cultivadores que atingem um certo reino têm a obrigação de orientar cultivadores iniciantes</li><li>Cultivadores avançados têm a obrigação de participar de assuntos públicos como manutenção de âncoras e proteção civilizacional</li><li>O cultivador é responsável pelas consequências de seu próprio comportamento de cultivo, não pode transferir a culpa</li><li>Quando a civilização enfrenta uma crise, os cultivadores avançados têm a obrigação de se apresentar</li></ul><h2 id="iii-tabus-absolutos-do-cultivo" tabindex="-1">III. Tabus Absolutos do Cultivo <a class="header-anchor" href="#iii-tabus-absolutos-do-cultivo" aria-label="Permalink to &quot;III. Tabus Absolutos do Cultivo&quot;">​</a></h2><p>Os seguintes comportamentos pertencem aos &quot;tabus absolutos&quot; do cultivo, e nenhum cultivador pode tocá-los em nenhuma circunstância; os violadores receberão as sanções mais severas:</p><table tabindex="0"><thead><tr><th>Tipo de Tabu</th><th>Comportamento Específico</th><th>Medida de Sanção</th></tr></thead><tbody><tr><td>Saque de Origem</td><td>Devorar ou saquear a origem ou núcleo vital de outras vidas</td><td>Abolição do cultivo, prisão perpétua, em casos graves aniquilação da origem</td></tr><tr><td>Escravidão de Alma</td><td>Transformar outras vidas em ferramentas por meio de controle de alma, escravidão mental, etc.</td><td>Abolição do cultivo, reeducação ética forçada, privação perpétua do direito de cultivo</td></tr><tr><td>Genocídio</td><td>Realizar massacre sistemático ou extermínio de uma raça com fins de cultivo</td><td>Julgamento supremo do Tribunal de Âncora, pena de morte</td></tr><tr><td>Destruição de Plano</td><td>Destruir um plano inteiro para obter recursos ou poder</td><td>Pena de morte, e assumir toda a responsabilidade pela reparação do plano</td></tr><tr><td>Experimento Desumano</td><td>Realizar experimentos de cultivo desumanos em vidas inteligentes</td><td>Abolição do cultivo, prisão perpétua, destruição total dos resultados da pesquisa</td></tr><tr><td>Crime Temporal</td><td>Usar a capacidade de retrocesso temporal para realizar adulteração histórica ou assassinato em larga escala</td><td>Pena de morte, e privação perpétua de capacidades relacionadas ao tempo</td></tr><tr><td>Poluição de Lei</td><td>Poluir deliberadamente as leis de origem do universo, causando danos irreversíveis ao universo como um todo</td><td>Pena de morte, e o órgão supremo da civilização executa a purificação da lei</td></tr></tbody></table><p>A definição dos tabus absolutos reflete a posição firme da civilização simbiótica em relação à linha de base ética do cultivo. Esses tabus não têm &quot;zona cinzenta&quot;, não têm &quot;atenuantes&quot;, e qualquer comportamento que toque um tabu absoluto receberá a sanção mais severa.</p><h2 id="iv-zona-cinzenta-da-etica-do-cultivo-e-principios-de-tratamento" tabindex="-1">IV. Zona Cinzenta da Ética do Cultivo e Princípios de Tratamento <a class="header-anchor" href="#iv-zona-cinzenta-da-etica-do-cultivo-e-principios-de-tratamento" aria-label="Permalink to &quot;IV. Zona Cinzenta da Ética do Cultivo e Princípios de Tratamento&quot;">​</a></h2><p>Além dos tabus claros, existem algumas &quot;zonas cinzentas&quot; na ética do cultivo — esses comportamentos em si não são absolutamente bons ou maus, e sua natureza ética depende da situação, motivo, método e consequência específicos. Para a zona cinzenta, a civilização simbiótica adota os seguintes princípios de tratamento:</p><h3 id="_4-1-zonas-cinzentas-comuns" tabindex="-1">4.1 Zonas Cinzentas Comuns <a class="header-anchor" href="#_4-1-zonas-cinzentas-comuns" aria-label="Permalink to &quot;4.1 Zonas Cinzentas Comuns&quot;">​</a></h3><ul><li><strong>Danos no cultivo de batalha</strong>: Os cultivadores podem causar danos uns aos outros no treinamento de combate; se esse dano é ético depende de se ambas as partes deram consentimento informado e se o dano está dentro de limites razoáveis</li><li><strong>Competição por recursos</strong>: Se a competição entre cultivadores por recursos raros é ética depende de se o método de competição é justo e se as regras antimonopólio são seguidas</li><li><strong>Assimetria de poder na relação mestre-discípulo</strong>: Existe naturalmente uma assimetria de poder entre mestre e discípulo; se o mestre abusa do poder requer julgamento específico</li><li><strong>Assunção de riscos no cultivo</strong>: Alguns métodos de cultivo são inerentemente de alto risco; se o cultivador assume voluntariamente o risco é ético requer avaliação da informação sobre o risco e da existência de alternativas</li><li><strong>Cooperação de cultivo entre raças</strong>: A cooperação de cultivo entre diferentes raças pode envolver diferenças culturais e assimetria de poder, requerendo avaliação específica</li></ul><h3 id="_4-2-principios-de-tratamento" tabindex="-1">4.2 Princípios de Tratamento <a class="header-anchor" href="#_4-2-principios-de-tratamento" aria-label="Permalink to &quot;4.2 Princípios de Tratamento&quot;">​</a></h3><p>Para questões éticas na zona cinzenta, a civilização simbiótica adota o método de &quot;análise de situação específica + avaliação do comitê ético + orientação por precedentes&quot;:</p><ol><li><strong>Análise de situação específica</strong>: Não se faz &quot;corte único&quot;; o julgamento é feito de forma abrangente com base na situação, motivo, método e consequência específicos</li><li><strong>Avaliação do comitê ético</strong>: Para questões éticas complexas, são submetidas ao &quot;Comitê Ético&quot; subordinado ao Tribunal de Âncora para avaliação profissional</li><li><strong>Orientação por precedentes</strong>: Os resultados da avaliação do comitê ético formam precedentes, fornecendo orientação para casos semelhantes subsequentes</li><li><strong>Educação prioritária</strong>: Para comportamentos inadequados na zona cinzenta, prioriza-se a educação e correção, em vez de sanções severas diretas</li><li><strong>Ajuste dinâmico</strong>: Com o desenvolvimento da civilização e o aprofundamento da compreensão ética, os critérios de julgamento da zona cinzenta podem ser ajustados dinamicamente</li></ol><h2 id="v-educacao-e-interiorizacao-da-etica-do-cultivo" tabindex="-1">V. Educação e Interiorização da Ética do Cultivo <a class="header-anchor" href="#v-educacao-e-interiorizacao-da-etica-do-cultivo" aria-label="Permalink to &quot;V. Educação e Interiorização da Ética do Cultivo&quot;">​</a></h2><p>A manutenção da ética do cultivo não pode depender apenas de sanções e supervisão externas, mas requer o reconhecimento e interiorização dos cultivadores a partir do fundo do coração. A civilização simbiótica estabeleceu um sistema educacional sistemático de ética do cultivo:</p><h3 id="_5-1-educacao-basica" tabindex="-1">5.1 Educação Básica <a class="header-anchor" href="#_5-1-educacao-basica" aria-label="Permalink to &quot;5.1 Educação Básica&quot;">​</a></h3><ul><li>A ética do cultivo é um curso obrigatório para todos os cultivadores, e a educação ética sistemática deve ser recebida a partir do Reino de Sentimento Original</li><li>O conteúdo educacional inclui princípios éticos, lista de tabus, análise de casos, simulação de situações, etc.</li><li>Os métodos educacionais incluem ensino em sala de aula, discussão de casos, representação de papéis, ensino pessoal do mestre, etc.</li></ul><h3 id="_5-2-educacao-avancada" tabindex="-1">5.2 Educação Avançada <a class="header-anchor" href="#_5-2-educacao-avancada" aria-label="Permalink to &quot;5.2 Educação Avançada&quot;">​</a></h3><ul><li>Com o aumento do reino do cultivador, a profundidade e amplitude da educação ética também aumentam correspondentemente</li><li>Os cultivadores avançados precisam aprender questões éticas mais complexas (como ética entre planos, ética temporal, ética da criação, etc.)</li><li>Cultivadores acima do Reino da Origem do Caminho precisam passar no &quot;Exame Ético de Alto Nível&quot; antes de continuar a aumentar seu reino</li></ul><h3 id="_5-3-interiorizacao-na-pratica" tabindex="-1">5.3 Interiorização na Prática <a class="header-anchor" href="#_5-3-interiorizacao-na-pratica" aria-label="Permalink to &quot;5.3 Interiorização na Prática&quot;">​</a></h3><ul><li>Incentivar os cultivadores a praticar os princípios éticos no cultivo diário, transformando os requisitos éticos em hábitos de comportamento conscientes</li><li>Estabelecer um sistema de seleção de &quot;Modelos Éticos&quot;, reconhecendo cultivadores com desempenho excepcional em ética do cultivo</li><li>O mestre tem a obrigação de transmitir o espírito ético ao mesmo tempo que transmite as técnicas de cultivo, alcançando a &quot;transmissão conjunta do caminho e da técnica&quot;</li></ul><h2 id="vi-supervisao-e-execucao-da-etica-do-cultivo" tabindex="-1">VI. Supervisão e Execução da Ética do Cultivo <a class="header-anchor" href="#vi-supervisao-e-execucao-da-etica-do-cultivo" aria-label="Permalink to &quot;VI. Supervisão e Execução da Ética do Cultivo&quot;">​</a></h2><h3 id="_6-1-mecanismo-de-supervisao" tabindex="-1">6.1 Mecanismo de Supervisão <a class="header-anchor" href="#_6-1-mecanismo-de-supervisao" aria-label="Permalink to &quot;6.1 Mecanismo de Supervisão&quot;">​</a></h3><ul><li><strong>Monitoramento da Rede de Âncora</strong>: A rede de âncora monitora continuamente o comportamento de cultivo dos cultivadores e alerta prontamente sobre comportamentos suspeitos de violação ética</li><li><strong>Sistema de denúncia ética</strong>: Qualquer vida pode denunciar comportamentos que violem a ética do cultivo ao Tribunal Ético do Tribunal de Âncora, e o denunciante é protegido</li><li><strong>Avaliação ética periódica</strong>: Cultivadores acima do Reino da Origem da Lei precisam passar por uma avaliação ética por ano, e os resultados são registrados no arquivo pessoal de cultivo</li><li><strong>Supervisão de organizações sociais</strong>: Incentivar várias organizações de cultivadores, comunidades raciais, etc., a realizar supervisão interna da ética do cultivo de seus membros</li></ul><h3 id="_6-2-mecanismo-de-execucao" tabindex="-1">6.2 Mecanismo de Execução <a class="header-anchor" href="#_6-2-mecanismo-de-execucao" aria-label="Permalink to &quot;6.2 Mecanismo de Execução&quot;">​</a></h3><ul><li><strong>Tribunal Ético</strong>: O Tribunal de Âncora tem um Tribunal Ético especial, responsável por julgar casos de ética do cultivo</li><li><strong>Sanções graduais</strong>: De acordo com a gravidade da violação ética, são aplicadas sanções graduais que vão desde advertência, multa, dedução de valor de contribuição, restrição de direitos de cultivo, abolição do cultivo até prisão perpétua e pena de morte</li><li><strong>Reeducação ética</strong>: Para violadores com vontade de arrependimento, a reeducação ética pode ser realizada simultaneamente com a sanção; após o sucesso da reeducação, os direitos podem ser parcialmente restaurados</li><li><strong>Registro de antecedentes</strong>: Os registros de violação da ética do cultivo serão permanentemente registrados no arquivo pessoal, afetando a certificação de reino subsequente, distribuição de recursos, solicitação de cargos públicos, etc.</li></ul><h2 id="vii-expansao-dinamica-dos-limites-do-cultivo" tabindex="-1">VII. Expansão Dinâmica dos Limites do Cultivo <a class="header-anchor" href="#vii-expansao-dinamica-dos-limites-do-cultivo" aria-label="Permalink to &quot;VII. Expansão Dinâmica dos Limites do Cultivo&quot;">​</a></h2><p>A ética e os limites do cultivo não são dogmas imutáveis, mas normas vivas que se ajustam dinamicamente com o desenvolvimento da civilização, o progresso da tecnologia e o aprofundamento da compreensão. A civilização simbiótica estabeleceu um mecanismo de expansão dinâmica dos limites do cultivo:</p><ol><li><strong>Avaliação ética de novas tecnologias</strong>: Sempre que surge uma nova tecnologia de cultivo ou aplicação de lei, primeiro é feita uma avaliação ética, e só após a aprovação ela pode ser promovida</li><li><strong>Discussão ética de novos cenários</strong>: Quando a civilização entra em um novo estágio de desenvolvimento (como a era entre planos, a era interestelar, etc.), são organizadas discussões éticas especiais para formular normas éticas adaptadas aos novos cenários</li><li><strong>Revisão periódica das normas éticas</strong>: As normas específicas da ética do cultivo são revisadas uma vez a cada cinquenta anos, e o processo de revisão consulta amplamente as opiniões de todas as vidas</li><li><strong>Acumulação contínua de precedentes éticos</strong>: Os julgamentos do Tribunal Ético formam precedentes, enriquecendo e refinando continuamente o conteúdo específico da ética do cultivo</li></ol><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A ética e os limites do cultivo são o pilar central da civilização espiritual da Civilização Simbiótica de Âncora. Ela responde a uma questão fundamental: &quot;Que tipo de pessoa o cultivador deve ser?&quot; A resposta da civilização simbiótica é: o cultivador deve ser uma pessoa com poder, mas ainda mais com moral; deve ser uma pessoa que unifica a evolução pessoal e a simbiose de todas as raças; deve ser uma pessoa que busca o poder, mas nunca é escravizada por ele. A ética do cultivo não é uma restrição ao poder, mas uma sublimação do poder — ela garante que o poder sempre sirva à dignidade da vida e ao progresso da civilização, em vez de se tornar uma ferramenta de destruição e saque. Em um universo onde o poder pode mover montanhas e encher mares, criar e destruir mundos, a ética do cultivo é a última e mais importante linha de defesa para proteger a linha de base da civilização.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>04-反掠夺主义核心论纲 (Compêndio Central do Antissaque)</li><li>17-位面至高强者标准 (Padrão do Mais Poderoso do Plano)</li><li>48-司法体系与裁决机制 (Sistema Judiciário e Mecanismo de Adjudicação)</li></ul>',56)])])}const v=a(s,[["render",r]]);export{p as __pageData,v as default};
